    border-radius: 12px;
    padding: 24px;
    transition: all 0.3s ease;
}

.form-field:hover {
    border-color: var(--primary);
    box-shadow: 0 4px 12px rgba(99, 102, 241, 0.1);
}

.question-header {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 12px;
}

.question-header h2 {
    font-size: 1.3rem;
    font-weight: 600;
    color: var(--text-primary);
}

.help-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    background: var(--bg-tertiary);
    border: 1px solid var(--border);
    border-radius: 50%;
    font-size: 0.75rem;
    color: var(--text-secondary);
    cursor: help;
    font-weight: 600;
}

.question-text {
    font-size: 1rem;
    color: var(--text-primary);
    margin-bottom: 12px;
    font-weight: 500;
}

.help-text {
    background: rgba(99, 102, 241, 0.1);
    border-left: 3px solid var(--primary);
    padding: 12px 16px;
    border-radius: 4px;
    font-size: 0.9rem;
    color: var(--text-secondary);
    margin-bottom: 16px;
}

.options {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.option {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 16px;
    background: var(--bg-tertiary);
    border: 1px solid var(--border);
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s ease;
    user-select: none;
}

.option:hover {
    background: rgba(99, 102, 241, 0.15);
    border-color: var(--primary);
}

.option input[type="checkbox"] {
    width: 20px;
    height: 20px;
    cursor: pointer;
    accent-color: var(--primary);
    flex-shrink: 0;
}

.option span {
    color: var(--text-primary);
    font-weight: 500;
    flex: 1;
}

.option input[type="checkbox"]:checked + span {
    color: var(--primary);
}

.option input[type="checkbox"]:focus {
    outline: 2px solid var(--primary);
    outline-offset: 2px;
}

.submit-btn {
    padding: 14px 28px;
    background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%);
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 16px;
}

.submit-btn:hover {
    background: linear-gradient(135deg, var(--primary-hover) 0%, #7c3aed 100%);
    transform: translateY(-2px);
    box-shadow: 0 8px 16px rgba(99, 102, 241, 0.3);
}

.submit-btn:active {
    transform: translateY(0);
    box-shadow: 0 4px 8px rgba(99, 102, 241, 0.2);
}

.result {
    margin-top: 24px;
    padding: 20px 24px;
    border-radius: 8px;
    display: none;
    text-align: center;
    animation: slideIn 0.3s ease;
}

.result.show {
    display: block;
}

.result.success {
    background: rgba(16, 185, 129, 0.15);
    border: 1px solid var(--success);
    color: var(--success);
}

.result.partial {
    background: rgba(168, 85, 247, 0.15);
    border: 1px solid #a855f7;
    color: #a855f7;
}

.result.error {
    background: rgba(239, 68, 68, 0.15);
    border: 1px solid var(--error);
    color: var(--error);
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@media (max-width: 600px) {
    header h1 {
        font-size: 1.8rem;
