AssistantMessageToolRequest(name='create', tool_call_id='tooluse_Ba89uvC612JIbsgijnEsre', arguments={'file_text': 'const quizForm = document.getElementById('quizForm');
const resultDiv = document.getElementById('result');

const correctAnswers = {
    question1: ['python', 'javascript', 'ruby'],
    question2: ['cpp', 'rust', 'go'],
    question3: ['python', 'r', 'julia']
};

quizForm.addEventListener('submit', function(e) {
    e.preventDefault();
    evaluateQuiz();
});

function evaluateQuiz() {
    let totalCorrect = 0;
    let totalPossible = 0;
    let questionResults = [];

    for (let question in correctAnswers) {
        const checkboxes = document.querySelectorAll(`input[name="${question}"]`);
        const selectedAnswers = Array.from(checkboxes)
            .filter(cb => cb.checked)
            .map(cb => cb.value);

        const correct = correctAnswers[question];
        totalPossible += correct.length;

        const correctSelected = selectedAnswers.filter(answer => correct.includes(answer)).length;
        const incorrectSelected = selectedAnswers.filter(answer => !correct.includes(answer)).length;

        totalCorrect += correctSelected;

        questionResults.push({
            question,
            selectedAnswers,
            correctAnswers: correct,
            correctSelected,
            incorrectSelected,
            isFullyCorrect: correctSelected === correct.length && incorrectSelected === 0
        });
    }

    displayResult(questionResults, totalCorrect, totalPossible);
}

function displayResult(results, totalCorrect, totalPossible) {
    let html = '<div class="result-content">';

    for (let i = 0; i < results.length; i++) {
        const result = results[i];
        const questionNum = i + 1;
        const questionLabel = `Question ${questionNum}`;
        const status = result.isFullyCorrect ? '✓' : '✗';

        html += `
            <div class="result-item ${result.isFullyCorrect ? 'correct' : 'incorrect'}">
                <strong>${questionLabel} ${status}</strong>
                <p>You selected: ${result.selectedAnswers.length > 0 ? result.selectedAnswers.join(', ') : 'nothing'}</p>
                <p>Correct answers: ${result.correctAnswers.join(', ')}</p>
            </div>
        `;
    }

    const score = totalCorrect;
    const percentage = totalPossible > 0 ? Math.round((score / totalPossible) * 100) : 0;
    const perfectionPercentage = 100;

    let scoreMessage = '';
    let scoreClass = '';

    if (percentage === perfectionPercentage) {
        scoreMessage = `Perfect! You got all ${totalPossible} correct! 🎉`;
        scoreClass = 'success';
    } else if (percentage >= 75) {
        scoreMessage = `Great job! You got ${score}/${totalPossible} correct (${percentage}%)`;
        scoreClass = 'partial';
    } else if (percentage >= 50) {
        scoreMessage = `Good effort! You got ${score}/${totalPossible} correct (${percentage}%)`;
        scoreClass = 'partial';
    } else {
        scoreMessage = `You got ${score}/${totalPossible} correct (${percentage}%). Keep learning! 📚`;
        scoreClass = 'error';
    }

    html += `
        <div class="score-summary">
            <h3>${scoreMessage}</h3>
        </div>
    </div>`;

    resultDiv.innerHTML = html;
    resultDiv.className = `result show ${scoreClass}`;
    resultDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}
